#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";

const sourceRoot = process.argv[2];
if (!sourceRoot) {
  console.error("Usage: node Scripts/normalize-marathi-editorial.mjs <unpacked-English-assets-dir>");
  process.exit(2);
}

const projectRoot = path.resolve(import.meta.dirname, "..");
const translationsRoot = path.join(
  projectRoot,
  "Sources/StardewTranslationInstaller/Resources/ModPayload/assets/translations",
);
const marathiRoot = path.join(translationsRoot, "marathi");
const overrides = JSON.parse(fs.readFileSync(
  path.join(projectRoot, "Documentation/marathi-editorial-overrides.json"),
  "utf8",
));
const englishGlossary = JSON.parse(fs.readFileSync(
  path.join(projectRoot, "Documentation/glossary/glossary.en.json"),
  "utf8",
));
const marathiGlossary = JSON.parse(fs.readFileSync(
  path.join(projectRoot, "Documentation/glossary/glossary.mr.json"),
  "utf8",
)).mr;
const glossaryExactMap = new Map();
const glossaryConflicts = new Set();
function addGlossaryExact(source, translated) {
  if (!source || !translated) return;
  if (glossaryExactMap.has(source) && glossaryExactMap.get(source) !== translated) {
    glossaryConflicts.add(source);
  } else glossaryExactMap.set(source, translated);
}
for (const entry of englishGlossary) {
  const translated = marathiGlossary[entry.id]?.term;
  addGlossaryExact(entry.term, translated);
  const sourceParts = entry.term.split(" / ");
  const translatedParts = translated?.split(" / ") ?? [];
  if (sourceParts.length === translatedParts.length) {
    sourceParts.forEach((source, index) => addGlossaryExact(source, translatedParts[index]));
  }
}
for (const conflict of glossaryConflicts) glossaryExactMap.delete(conflict);

function readJSON(file) {
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function listJSONFiles(directory) {
  return fs.readdirSync(directory).filter((file) => file.endsWith(".json")).sort();
}

function records(folder) {
  const result = new Map();
  for (const relative of listJSONFiles(folder)) {
    const document = readJSON(path.join(folder, relative));
    for (const change of document.Changes ?? []) {
      for (const [key, value] of Object.entries(change.Entries ?? {})) {
        result.set(`${change.Target}\0${key}`, value);
      }
    }
  }
  return result;
}

const russian = records(path.join(translationsRoot, "russian"));
const polish = records(path.join(translationsRoot, "polish"));
const sourceCache = new Map();
function sourceContent(target) {
  if (!sourceCache.has(target)) {
    sourceCache.set(target, readJSON(path.join(sourceRoot, `${target}.json`)).content);
  }
  return sourceCache.get(target);
}

function restoreReferenceTechnicalFields(id, english, marathi) {
  let result = marathi;
  for (const delimiter of ["^", "/"]) {
    const sourceParts = english.split(delimiter);
    const russianParts = russian.get(id)?.split(delimiter) ?? [];
    const polishParts = polish.get(id)?.split(delimiter) ?? [];
    const marathiParts = result.split(delimiter);
    if (
      sourceParts.length < 2
      || sourceParts.length !== russianParts.length
      || sourceParts.length !== polishParts.length
      || sourceParts.length !== marathiParts.length
    ) continue;
    for (let index = 0; index < sourceParts.length; index += 1) {
      if (
        russianParts[index] === sourceParts[index]
        && polishParts[index] === sourceParts[index]
      ) {
        marathiParts[index] = sourceParts[index];
      }
    }
    result = marathiParts.join(delimiter);
  }
  return result;
}

