const contextualEditorialReplacements = new Map();
for (const [id, replacements] of contextualEditorialReplacementEntries) {
  contextualEditorialReplacements.set(id, [
    ...(contextualEditorialReplacements.get(id) ?? []),
    ...replacements,
  ]);
}

function applyContextualEditorialReplacements(id, value) {
  let result = value;
  for (const [source, replacement] of contextualEditorialReplacements.get(id) ?? []) {
    result = result.replaceAll(source, replacement);
  }
  if (id === "Data/Events/Woods\u00002120303/S 23/i 724/t 600 1900") {
    result = result.replace(/हूओ+\$h#\$b#/u, "हूऽऽ... तो वास... किती गोड पदार्थ आहे!$h#$b#");
  }
  return result;
}

function normalizeFormatting(value) {
  if (!/\p{Script=Devanagari}/u.test(value)) return value;
  return value
    .replace(/'([^'\n]+)'/gu, "‘$1’")
    .replace(/(?<=\p{Script=Devanagari})‘/gu, " ‘")
    .replace(/’(?=\p{Script=Devanagari})/gu, "’ ")
    .replace(/(?<=\p{Script=Devanagari})@/gu, " @")
    .replace(/@(?=\p{Script=Devanagari})/gu, "@ ")
    .replace(/(?<=\p{Script=Devanagari})(\{\d+\})/gu, " $1")
    .replace(/(\{\d+\})(?!(?:चा|ची|चे|च्या|ला|ने|मध्ये|वर|कडे|सोबत|पासून|साठी|ही|च))(?=\p{Script=Devanagari})/gu, "$1 ")
    .replace(/(\d)(?!(?:वा|वी|वे|व्या|चा|ची|चे))(?=\p{Script=Devanagari})/gu, "$1 ");
}

let technicalRestorations = 0;
let manualOverrides = 0;
let terminologyChanges = 0;
let formattingChanges = 0;
let glossaryExactRestorations = 0;
let contextualEditorialChanges = 0;
for (const relative of listJSONFiles(marathiRoot)) {
  const file = path.join(marathiRoot, relative);
  const document = readJSON(file);
  for (const change of document.Changes ?? []) {
    const source = sourceContent(change.Target);
    for (const [key, current] of Object.entries(change.Entries ?? {})) {
      const id = `${change.Target}\0${key}`;
      const glossaryExact = glossaryExactMap.get(source[key]);
      if (glossaryExact !== undefined) {
        if (change.Entries[key] !== glossaryExact) {
          change.Entries[key] = glossaryExact;
          glossaryExactRestorations += 1;
        }
        continue;
      }
      const restored = restoreReferenceTechnicalFields(id, source[key], current);
      if (restored !== current) {
        change.Entries[key] = restored;
        technicalRestorations += 1;
      }
      const terminology = applyTerminology(change.Target, key, source[key], change.Entries[key]);
      if (terminology !== change.Entries[key]) {
        change.Entries[key] = terminology;
        terminologyChanges += 1;
      }
      const contextualEditorial = applyContextualEditorialReplacements(id, change.Entries[key]);
      if (contextualEditorial !== change.Entries[key]) {
        change.Entries[key] = contextualEditorial;
        contextualEditorialChanges += 1;
      }
      const formatted = normalizeFormatting(change.Entries[key]);
      if (formatted !== change.Entries[key]) {
        change.Entries[key] = formatted;
        formattingChanges += 1;
      }
      if (Object.hasOwn(overrides, id) && change.Entries[key] !== overrides[id]) {
        change.Entries[key] = overrides[id];
        manualOverrides += 1;
      }
      const canonicalNames = change.Entries[key]
        .replace(/एबिगेल/gu, "अबिगेल")
        .replace(/अबीगेल/gu, "अबिगेल")
        .replace(/लीआ/gu, "लिया")
        .replace(/जहाजाचे चिन्ह/gu, "पात्राचे चिन्ह");
      if (canonicalNames !== change.Entries[key]) {
        change.Entries[key] = canonicalNames;
        terminologyChanges += 1;
      }
    }
  }
  fs.writeFileSync(file, `${JSON.stringify(document, null, 2)}\n`);
}

console.log(JSON.stringify({
  technicalRestorations,
  glossaryExactRestorations,
  terminologyChanges,
  contextualEditorialChanges,
  formattingChanges,
  manualOverrides,
}, null, 2));
